import{_ as t,a as i}from"./chunks/EditCollection3.DJXc7XnK.js";import{_ as a,c as o,a2 as s,o as n}from"./chunks/framework.CoXjB5sU.js";const l="/assets/CreatePublishSelection1.Br6WBesf.png",r="/assets/CreatePublishForm.BrR4za1_.png",c="/assets/CreatePublishFormManuscript.CpNbGbgS.png",h="/assets/CreatePublishResume.ClPUTxU4.png",p="/assets/EditPublishedElement.D8VCK95Z.png",u="/assets/EditCollection.QuzlBMi5.png",d="/assets/CreatePublishHandle.BMhHVZwB.png",m="/assets/BrowsePublishedElementsDetail.CnGAarna.png",b="/assets/BrowsePublishedElementsDetailItem.DrSkPDgI.png",C=JSON.parse('{"title":"Publish a dataset into Browse","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/publishing-calculations/publish-process.md","filePath":"doc/guides/usage/publishing-calculations/publish-process.md"}'),g={name:"doc/guides/usage/publishing-calculations/publish-process.md"};function f(w,e,P,k,y,v){return n(),o("div",null,e[0]||(e[0]=[s('<h1 id="publish-a-dataset-into-browse" tabindex="-1">Publish a dataset into Browse <a class="header-anchor" href="#publish-a-dataset-into-browse" aria-label="Permalink to &quot;Publish a dataset into Browse&quot;">​</a></h1><p>Calculations uploaded into the Create module are only accessible to registered ioChem-BD users, usually a small group of individuals that conform the research group or center. Their calculations will not be publicly accessible until they are published in the <strong>Browse module</strong>, the public module of <strong>ioChem-BD</strong>.</p><p>Before moving to the publication mechanism, it is interesting to read again the section about the organizational elements that conform each module: <a href="/doc/what-is-iochem-bd.html#modular-architecture">ioChem-BD organizational elements</a>.</p><p>Published projects become Collections and published calculations become Items in the Browse module, a mere grammatical change to align with the <a href="https://www.dspace.org/" target="_blank" rel="noreferrer">DSpace software</a> naming convention.</p><p>Once published, both elements are linkable, searchable and viewable publicly.</p><h2 id="publication-requirements" tabindex="-1">Publication requirements <a class="header-anchor" href="#publication-requirements" aria-label="Permalink to &quot;Publication requirements&quot;">​</a></h2><p>To publish, your user group must have a <strong>publishing community</strong> assigned in the Browse module. Creating communities and assigning them to groups falls upon the ioChem-BD system administrator and is described on the <a href="./../../installation/publishing-endpoints-definition.html">publishing endpoints definition</a> page.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Since ioChem-BD v3.0, you can only publish an entire project, not part of its content. Select the <strong>project only</strong> before publishing; if other content is selected, the publish option will not be available.</p></div><h2 id="publication-steps" tabindex="-1">Publication steps <a class="header-anchor" href="#publication-steps" aria-label="Permalink to &quot;Publication steps&quot;">​</a></h2><h3 id="select-the-elements-to-publish" tabindex="-1">Select the elements to publish <a class="header-anchor" href="#select-the-elements-to-publish" aria-label="Permalink to &quot;Select the elements to publish&quot;">​</a></h3><p>On the Create module, navigate to the project to publish in the <strong>My workspace</strong> tab.</p><p>Select it, right click it and choose <strong>Browse module → Publish</strong> from the context menu.</p><p><img src="'+l+'" alt="Project selection"></p><p>If an error message appears at this point, please read the FAQ entry about <a href="/doc/faqs/general/create-publish-error.html">no publishing community defined</a>.</p><h3 id="publication-form" tabindex="-1">Publication form <a class="header-anchor" href="#publication-form" aria-label="Permalink to &quot;Publication form&quot;">​</a></h3><p>After clicking <strong>Publish</strong>, the publication dialog appears. It consolidates all publication settings into a single form.</p><p><img src="'+r+'" alt="Publication form"></p><p>At the top of the dialog, a summary shows the project name and the number of calculations to publish. You must first select the <strong>destination community</strong> from the dropdown before the form fields become active.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you have multiple communities available, select the one where you want your dataset to appear.</p></div><p>The form is organized into six numbered sections:</p><h4 id="section-1-collection" tabindex="-1">Section 1: Collection <a class="header-anchor" href="#section-1-collection" aria-label="Permalink to &quot;Section 1: Collection&quot;">​</a></h4><p>The title and description of the collection that will hold the dataset in Browse. Both fields are required.</p><h4 id="section-2-dataset-type" tabindex="-1">Section 2: Dataset Type <a class="header-anchor" href="#section-2-dataset-type" aria-label="Permalink to &quot;Section 2: Dataset Type&quot;">​</a></h4><p>This section specifies whether your dataset is independent or linked to a manuscript:</p><ul><li><strong>Independent Dataset</strong>: Your data is standalone and not associated with any publication.</li><li><strong>Linked to Manuscript</strong>: Your dataset is supplementary material for a paper. When selected, additional fields appear:</li></ul><p><img src="'+c+'" alt="Manuscript information"></p><blockquote><ul><li><strong>DOI (Digital Object Identifier)</strong>: The DOI of the related manuscript (e.g., <code>10.1021/acscatal.xxxxxx</code>)</li><li><strong>Manuscript is a pre-print (not yet published)</strong>: Check it if the paper is not published yet; you can provide the information later.</li></ul></blockquote><h4 id="section-3-authors-affiliations" tabindex="-1">Section 3: Authors &amp; Affiliations <a class="header-anchor" href="#section-3-authors-affiliations" aria-label="Permalink to &quot;Section 3: Authors &amp; Affiliations&quot;">​</a></h4><p>Adds the dataset authors:</p><ol><li>Type in the author search box to find existing platform users (external names are also accepted using the <strong>Surname, Name</strong> format)</li><li>Click <strong>Add</strong></li><li>Authors appear as chips that can be removed by clicking the × icon</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The current user is automatically added as the first author.</p></div><h4 id="section-4-sponsoring-agencies-institutions" tabindex="-1">Section 4: Sponsoring agencies / Institutions <a class="header-anchor" href="#section-4-sponsoring-agencies-institutions" aria-label="Permalink to &quot;Section 4: Sponsoring agencies / Institutions&quot;">​</a></h4><p>Adds the sponsoring agencies or institutions of the project: type the name, click <strong>Add</strong>, and they appear as removable chips. An optional <strong>Project code</strong> field records the scientific or financial project reference.</p><h4 id="section-5-discovery" tabindex="-1">Section 5: Discovery <a class="header-anchor" href="#section-5-discovery" aria-label="Permalink to &quot;Section 5: Discovery&quot;">​</a></h4><p>Keywords that make your dataset discoverable: type a term (existing or new), click <strong>Add</strong> and it becomes a removable chip. Adding relevant chemical and scientific terms helps other researchers find your data through Browse module searches.</p><h4 id="section-6-publication-options" tabindex="-1">Section 6: Publication Options <a class="header-anchor" href="#section-6-publication-options" aria-label="Permalink to &quot;Section 6: Publication Options&quot;">​</a></h4><ul><li><strong>Request a DOI for published project</strong>: When checked, a DOI will be requested for the published collection. You will be notified by email once it is assigned.</li><li><strong>Embargo published elements, content restricted only to reviewers</strong>: When checked, access to the published content is restricted to reviewers until the embargo is lifted. Read <a href="./embargo.html">Setting the embargo</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">DOI generation</p><p>DOI determination can take some minutes to resolve because it requires contacting third party services (CrossRef). Once the DOI has been assigned, you will receive an email with the DOI for the published collection.</p></div><h3 id="publishing-the-data" tabindex="-1">Publishing the data <a class="header-anchor" href="#publishing-the-data" aria-label="Permalink to &quot;Publishing the data&quot;">​</a></h3><p>Once the form is filled, click the <strong>Publish Data</strong> button. The publication process starts and a progress indicator shows its status; large projects can take a while.</p><h3 id="publication-resume" tabindex="-1">Publication resume <a class="header-anchor" href="#publication-resume" aria-label="Permalink to &quot;Publication resume&quot;">​</a></h3><p>After the process completes, a resume window shows the results:</p><p><img src="'+h+'" alt="Publication resume"></p><p>The resume displays:</p><ul><li>A success message with the publication summary</li><li><strong>View Published Project</strong>: the link to the new collection in the Browse module</li><li><strong>Peer Review Access</strong>: the reviewer link, when the embargo option was enabled</li></ul><p><img src="'+t+'" alt="Publication resume with embargo"></p><ul><li><strong>Project Management</strong>: the link to the collection editor, where you can modify properties or lift the embargo</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All administrative links shown in the resume can be accessed anytime through the edit icon of each published project in the Create module workspace tree.</p></div><h3 id="published-elements-manipulation" tabindex="-1">Published elements manipulation <a class="header-anchor" href="#published-elements-manipulation" aria-label="Permalink to &quot;Published elements manipulation&quot;">​</a></h3><p>Published projects display their <strong>handle</strong> in the workspace tree, together with an <strong>edit icon</strong> that opens the <em>Edit published collection</em> page.</p><p><img src="'+p+'" alt="Edit icon of a published project"></p><p>That page allows to:</p><ul><li>Change the published collection title, subtitle and description</li><li>Set the related article information (paper DOI)</li><li>Copy the reviewers link</li><li><a href="./embargo.html#lifting-the-embargo">Lift the embargo</a></li></ul><p><img src="'+u+'" alt="Published collection edition form"></p><p><img src="'+i+'" alt="Embargo and review link section"></p><h3 id="view-published-elements-from-create" tabindex="-1">View published elements from Create <a class="header-anchor" href="#view-published-elements-from-create" aria-label="Permalink to &quot;View published elements from Create&quot;">​</a></h3><p>The published projects and calculations display their handle in the workspace tree.</p><p><img src="'+d+'" alt="Publication handle"></p><p>Clicking on a project handle navigates to the published Browse content. Each collection holds multiple Items (calculations) inside.</p><p><img src="'+m+'" alt="Published collection items"></p><p>Each published item displays the uploaded input file, the converted CML output file, additional files and its metadata.</p><p><img src="'+b+'" alt="Published item detail"></p>',62)]))}const x=a(g,[["render",f]]);export{C as __pageData,x as default};
